/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The program expects exactly one command‑line argument: a Roman numeral
 * (upper‑ or lower‑case).  If the argument is a *valid* Roman numeral in
 * its canonical (modern) form and its value is in the range 1 … 3999,
 * the program prints the integer value followed by a newline.
 * Otherwise it prints the word “INVALID” followed by a newline.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63
#define MAX_VALUE     3999

static const struct {
    int value;
    const char *sym;
} roman_table[] = {
    {1000, "M"},
    { 900, "CM"},
    { 500, "D"},
    { 400, "CD"},
    { 100, "C"},
    {  90, "XC"},
    {  50, "L"},
    {  40, "XL"},
    {  10, "X"},
    {   9, "IX"},
    {   5, "V"},
    {   4, "IV"},
    {   1, "I"},
};

static int roman_char_value(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

static void int_to_roman(int n, char *out)
{
    char *p = out;
    for (size_t i = 0; i < sizeof roman_table / sizeof roman_table[0]; ++i) {
        while (n >= roman_table[i].value) {
            const char *sym = roman_table[i].sym;
            while (*sym) *p++ = *sym++;
            n -= roman_table[i].value;
        }
    }
    *p = '\0';
}

static int parse_roman(const char *s)
{
    int total = 0;
    int prev = 0;
    int repeat = 0; // count of additional repeats of the same symbol

    for (size_t i = 0; s[i] != '\0'; ++i) {
        int cur = roman_char_value(s[i]);
        if (cur == -1) return -1; // illegal character

        if (cur == prev) {
            ++repeat;
            if (cur == 5 || cur == 50 || cur == 500) // V, L, D may not repeat
                return -1;
            if (repeat > 2) // more than three total repetitions
                return -1;
        } else {
            repeat = 0;
        }

        if (prev && cur > prev) {
            // allowed subtractive pairs only
            if (!((prev == 1 && (cur == 5 || cur == 10)) ||
                  (prev == 10 && (cur == 50 || cur == 100)) ||
                  (prev == 100 && (cur == 500 || cur == 1000)))) {
                return -1;
            }
            total += cur - 2 * prev; // adjust for previously added prev
        } else {
            total += cur;
        }
        prev = cur;
    }
    return total;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    char upper[MAX_INPUT_LEN + 1];
    for (size_t i = 0; i < len; ++i) {
        char c = input[i];
        if ('a' <= c && c <= 'z') c = c - ('a' - 'A');
        upper[i] = c;
    }
    upper[len] = '\0';

    int value = parse_roman(upper);
    if (value <= 0 || value > MAX_VALUE) {
        puts("INVALID");
        return 0;
    }

    char canonical[64];
    int_to_roman(value, canonical);
    if (strcmp(canonical, upper) != 0) {
        puts("INVALID");
        return 0;
    }

    printf("%d\n", value);
    return 0;
}
